implementation:
#include <linux/usb.h>
#include <linux/dvb/usb.h>

void dvb_usb_disconnect(struct usb_interface *intf) {
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int interface_num = intf->cur_altsetting->desc.bInterfaceNumber;

    if (!d) {
        return;
    }

    if (d->props.exit) {
        d->props.exit(d);
    }

    dvb_usbv2_exit(d);

    printk(KERN_INFO "DVB USB device disconnected (interface %d).\n", interface_num);
}
